/* Minimal stand-in for i18next (written for the offline capture; the router
 * ships the real library). Supports what the router UI uses: use/init/t/on/
 * changeLanguage, and fires "loaded" after init, which starts each page. */
(function () {
  const listeners = {};
  let resources = {};
  function emit(evt, arg) { (listeners[evt] || []).forEach((cb) => cb(arg)); }
  window.i18next = {
    language: "en",
    languages: ["en"],
    use() { return this; },
    async init() {
      try { resources = await (await fetch("/js/locales/en.json")).json(); } catch (e) { resources = {}; }
      setTimeout(() => { emit("initialized", {}); emit("loaded", { en: { translation: true } }); }, 0);
      return (key) => this.t(key);
    },
    t(key, vars) {
      let text = Object.prototype.hasOwnProperty.call(resources, key) ? resources[key] : key;
      if (vars) text = text.replace(/{{\s*(\w+)\s*}}/g, (m, name) => (name in vars ? vars[name] : m));
      return text;
    },
    exists(key) { return Object.prototype.hasOwnProperty.call(resources, key); },
    on(evt, cb) { (listeners[evt] = listeners[evt] || []).push(cb); },
    off() {},
    changeLanguage(lng) { this.language = lng; emit("languageChanged", lng); return Promise.resolve(); },
  };
})();
